/usr/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from copy import deepcopy
from random import Random

from solution import schedule


def reference(jobs):
    pending = {job: set(dependencies) for job, dependencies in jobs.items()}
    missing = set().union(*pending.values()) - jobs.keys()
    if missing:
        return {\"missing\": sorted(missing)}

    waves = []
    while pending:
        ready = sorted(job for job, dependencies in pending.items()
                       if not dependencies.intersection(pending))
        if not ready:
            break
        waves.append(ready)
        for job in ready:
            del pending[job]
    return {\"waves\": waves, \"blocked\": sorted(pending)}


cases = [
    {},
    {\"root\": [], \"leaf\": [\"root\", \"root\"], \"second\": [], \"last\": [\"leaf\", \"second\"]},
    {\"self\": [\"self\"], \"after\": [\"self\"], \"free\": [], \"later\": [\"after\"]},
    {\"a\": [\"b\"], \"b\": [\"a\"], \"c\": [\"b\", \"free\"], \"free\": []},
    {\"a\": [\"a\", \"z\", \"z\"], \"b\": [\"y\", \"z\"]},
    {\"\": [], \"a\": [\"\"], \"я\": [], \"ё\": []},
]
rng = Random(2026)
for _ in range(1000):
    names = [str(i) for i in range(rng.randrange(20))]
    possible_dependencies = names + [\"missing\"] if rng.random() < 0.1 else names
    cases.append({name: rng.choices(possible_dependencies, k=rng.randrange(4))
                  for name in names})

for jobs in cases:
    original = deepcopy(jobs)
    expected = reference(jobs)
    assert schedule(jobs) == expected, (jobs, expected)
    assert jobs == original, jobs

names = [f\"job{i:05d}\" for i in range(10_000)]
chain = {names[0]: []}
chain.update({job: [previous] for previous, job in zip(names, names[1:])})
assert schedule(chain) == {\"waves\": [[name] for name in names], \"blocked\": []}
print(f\"{len(cases)} reference comparisons and a 10,000-job chain passed.\")
PY"

